# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">KUR\'AN KAVRAMLARININ AYETLERDEKİ BAĞLAMI: VELÎ, ADALET, ZULÜM, ŞEFAAT</text>\n  <rect x="20" y="45" width="155" height="195" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="97" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Velî (Dost / Vekil)</text>\n  <text x="97" y="90" text-anchor="middle" font-size="10" fill="#1e3a8a">• Dost, yardımcı, koruyucu.</text>\n  <text x="97" y="110" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">• Bakara, 2/257:</text>\n  <text x="97" y="126" text-anchor="middle" font-size="9.5" fill="#1e3a8a">"Allah iman edenlerin</text>\n  <text x="97" y="140" text-anchor="middle" font-size="9.5" fill="#1e3a8a">velîsidir; onları karanlıklardan</text>\n  <text x="97" y="154" text-anchor="middle" font-size="9.5" fill="#1e3a8a">aydınlığa (nura) çıkarır."</text>\n  <text x="97" y="176" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">• Yûnus, 10/62:</text>\n  <text x="97" y="192" text-anchor="middle" font-size="9.5" fill="#1e3a8a">Allah\'ın evliyâsı (dostları)</text>\n  <text x="97" y="206" text-anchor="middle" font-size="9.5" fill="#1e3a8a">iman ve takva sahipleridir.</text>\n  <rect x="188" y="45" width="155" height="195" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="265" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. Adalet (Kıst / Mizan)</text>\n  <text x="265" y="90" text-anchor="middle" font-size="10" fill="#14532d">• Hakkı sahibine vermek.</text>\n  <text x="265" y="110" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">• Nahl, 16/90:</text>\n  <text x="265" y="126" text-anchor="middle" font-size="9.5" fill="#14532d">"Şüphesiz Allah adaleti,</text>\n  <text x="265" y="140" text-anchor="middle" font-size="9.5" fill="#14532d">ihsanı ve akrabaya</text>\n  <text x="265" y="154" text-anchor="middle" font-size="9.5" fill="#14532d">vermeyi emreder..."</text>\n  <text x="265" y="176" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">• Nisâ, 4/135 &amp; Mâide, 8:</text>\n  <text x="265" y="192" text-anchor="middle" font-size="9.5" fill="#14532d">Kendimiz ve yakınlarımız</text>\n  <text x="265" y="206" text-anchor="middle" font-size="9.5" fill="#14532d">aleyhine de olsa adil şahitlik.</text>\n  <rect x="356" y="45" width="155" height="195" rx="8" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="433" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">3. Zulüm (Haksızlık)</text>\n  <text x="433" y="90" text-anchor="middle" font-size="10" fill="#7f1d1d">• Bir şeyi yerinden başka</text>\n  <text x="433" y="104" text-anchor="middle" font-size="10" fill="#7f1d1d">yere koymak, haddi aşmak.</text>\n  <text x="433" y="124" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">• Lokmân, 31/13:</text>\n  <text x="433" y="140" text-anchor="middle" font-size="9.5" fill="#7f1d1d">"Şüphesiz şirk (ortak</text>\n  <text x="433" y="154" text-anchor="middle" font-size="9.5" fill="#7f1d1d">koşmak) en büyük zulümdür."</text>\n  <text x="433" y="176" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">• Üç Boyutu:</text>\n  <text x="433" y="192" text-anchor="middle" font-size="9.5" fill="#7f1d1d">1. Şirk, 2. Kul hakkı,</text>\n  <text x="433" y="206" text-anchor="middle" font-size="9.5" fill="#7f1d1d">3. İnsanın nefsine zulmü.</text>\n  <rect x="525" y="45" width="155" height="195" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="602" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">4. Şefaat (Aracılık)</text>\n  <text x="602" y="90" text-anchor="middle" font-size="10" fill="#78350f">• Ahirette bağışlanma için</text>\n  <text x="602" y="104" text-anchor="middle" font-size="10" fill="#78350f">Allah katında dua/niyaz.</text>\n  <text x="602" y="124" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">• Bakara, 255 &amp; Enbiyâ, 28:</text>\n  <text x="602" y="140" text-anchor="middle" font-size="9.5" fill="#78350f">1. Allah\'ın <tspan font-weight="bold">izni</tspan> olması,</text>\n  <text x="602" y="156" text-anchor="middle" font-size="9.5" fill="#78350f">2. Şefaat edilecek kimseden</text>\n  <text x="602" y="170" text-anchor="middle" font-size="9.5" fill="#78350f">Allah\'ın <tspan font-weight="bold">razı (mümin)</tspan> olması.</text>\n  <text x="602" y="192" text-anchor="middle" font-size="10" font-weight="bold" fill="#92400e">• Zümer, 39/44:</text>\n  <text x="602" y="206" text-anchor="middle" font-size="9.5" fill="#78350f">"Şefaat tümüyle Allah\'ındır."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YÂSÎN, MÜLK VE NEBE\' SURELERİNDE TECVİT UYGULAMALARI</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Med (Uzatma) ve Vakıf Kuralları</text>\n  <text x="35" y="94" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Medd-i Muttasıl (Vacip):</tspan> Harf-i med ile</text>\n  <text x="43" y="110" font-size="10" fill="#1e3a8a">sebep-i med (hemze) <tspan font-weight="bold">aynı kelimede</tspan> (جَاءَ ، سَوَاءٌ).</text>\n  <text x="35" y="132" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Medd-i Munfasıl (Caiz):</tspan> Harf-i med ile</text>\n  <text x="43" y="148" font-size="10" fill="#1e3a8a">uzun hemze <tspan font-weight="bold">ayrı kelimelerde</tspan> (إِنَّا أَنْزَلْنَاهُ).</text>\n  <text x="35" y="170" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Medd-i Lâzım:</tspan> Harf-i medden sonra lâzım</text>\n  <text x="43" y="186" font-size="10" fill="#1e3a8a">sükûn gelmesi (يسٓ : Yâ-Sîîîn, 4 elif uzatılır).</text>\n  <text x="35" y="208" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Medd-i Ârız:</tspan> Durak (vakıf) yerinde geçici</text>\n  <text x="43" y="224" font-size="10" fill="#1e3a8a">sükûn nedeniyle uzatma (الْحَكِيمِ \u06dd ، الْعَلِيمُ \u06dd).</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Tenvin, Sâkin Nûn ve Özel Okunuşlar</text>\n  <text x="375" y="94" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">İhfâ:</tspan> 15 ihfâ harfinden biri gelince genizden</text>\n  <text x="383" y="110" font-size="10" fill="#14532d">tutarak okuma (أَنْذَرْتَهُمْ ، مَنْ خَشِيَ).</text>\n  <text x="375" y="132" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">İdğâm-ı Meal-Ğunne:</tspan> (ي م ن و) harfleriyle</text>\n  <text x="383" y="148" font-size="10" fill="#14532d">ğunneli katma (مَنْ يَقُولُ ، يَوْمَئِذٍ نَاعِمَةٌ).</text>\n  <text x="375" y="170" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">İdğâm-ı Bilâ-Ğunne:</tspan> (ل ر) ile ğunnesiz</text>\n  <text x="383" y="186" font-size="10" fill="#14532d">katma; <tspan font-weight="bold">Yâsîn 1-2 geçişinde (يسٓ وَالْقُرْآنِ)</tspan></text>\n  <text x="383" y="202" font-size="10" font-weight="bold" fill="#15803d">vav harfine rağmen İZHAR yapılır (İstisna)!</text>\n  <text x="375" y="222" font-size="10" fill="#14532d">• <tspan font-weight="bold">Yâsîn 52 (مَرْقَدِنَا ۜ هٰذَا):</tspan> Sekte (nefes almadan duruş).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">SEÇME SURELERİN (YÂSÎN, MÜLK, NEBE\') TEMA VE MESAJ ANALİZİ</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Yâsîn Suresi (Mekkî, 83 Ayet)</text>\n  <text x="32" y="92" font-size="10.5" font-weight="bold" fill="#b45309">• "Kur\'an\'ın Kalbi"</text>\n  <text x="32" y="112" font-size="10" fill="#78350f">• Hz. Peygamber\'in risaleti ve</text>\n  <text x="40" y="128" font-size="10" fill="#78350f">Kur\'an\'ın hikmetli bir kitap oluşu.</text>\n  <text x="32" y="148" font-size="10" fill="#78350f">• Antakya (Karye) halkı ve</text>\n  <text x="40" y="164" font-size="10" fill="#78350f">Habîb-i Neccâr kıssası.</text>\n  <text x="32" y="184" font-size="10" fill="#78350f">• Gece-gündüz, güneş ve ayın</text>\n  <text x="40" y="200" font-size="10" fill="#78350f">yörüngesi, ölü toprağın dirilişi</text>\n  <text x="40" y="216" font-size="10" font-weight="bold" fill="#92400e">ve "Kün fe-yekûn" (Ol der, olur).</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Mülk Suresi (Mekkî, 30 Ayet)</text>\n  <text x="257" y="92" font-size="10.5" font-weight="bold" fill="#1d4ed8">• "Tebâreke / Koruyucu (Mâni\'a)"</text>\n  <text x="257" y="112" font-size="10" fill="#1e3a8a">• Mutlak mülk ve hükümranlığın</text>\n  <text x="265" y="128" font-size="10" fill="#1e3a8a">Yüce Allah\'ın elinde olduğu.</text>\n  <text x="257" y="148" font-size="10" fill="#1e3a8a">• Ölüm ve hayatın "hanginizin daha</text>\n  <text x="265" y="164" font-size="10" fill="#1e3a8a">güzel amel yapacağını imtihan"</text>\n  <text x="265" y="180" font-size="10" fill="#1e3a8a">için yaratıldığı (Mülk, 67/2).</text>\n  <text x="257" y="200" font-size="10" fill="#1e3a8a">• Yedi kat gökte kusursuz nizam</text>\n  <text x="265" y="216" font-size="10" font-weight="bold" fill="#1e40af">ve uçan kuşların ibreti.</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Nebe\' Suresi (Mekkî, 40 Ayet)</text>\n  <text x="482" y="92" font-size="10.5" font-weight="bold" fill="#15803d">• "Amme / Büyük Haber"</text>\n  <text x="482" y="112" font-size="10" fill="#14532d">• 30. Cüzün ilk suresidir; "Büyük</text>\n  <text x="490" y="128" font-size="10" fill="#14532d">Haber (en-Nebeü\'l-Azîm)" olan</text>\n  <text x="490" y="144" font-size="10" fill="#14532d">kıyamet ve dirilişi konu alır.</text>\n  <text x="482" y="164" font-size="10" fill="#14532d">• Yeryüzünün döşek, dağların</text>\n  <text x="490" y="180" font-size="10" fill="#14532d">kazık, uykunun dinlenme oluşu.</text>\n  <text x="482" y="200" font-size="10" fill="#14532d">• <tspan font-weight="bold">38. Ayet:</tspan> Rahmân\'ın izni ve</text>\n  <text x="490" y="216" font-size="10" font-weight="bold" fill="#166534">doğru söz şartıyla şefaat.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
